-- Pumped: Curated Standard Strength Exercises Seed (56 exercises)
-- Generated by scripts/fetch-curated-exercises.mjs (idempotent upsert by slug)

INSERT INTO public.exercises (
  slug,
  name,
  muscle_group,
  secondary_muscles,
  equipment,
  tracking_type,
  media_gif_url,
  media_image_start_url,
  media_image_end_url,
  instructions,
  is_custom
)
VALUES
  ('barbell-bench-press', 'Barbell Bench Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-bench-press.gif', '/exercises/photos/barbell-bench-press-0.jpg', '/exercises/photos/barbell-bench-press-1.jpg', ARRAY['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.', 'After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], FALSE),
  ('incline-barbell-bench-press', 'Incline Barbell Bench Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/incline-barbell-bench-press.gif', '/exercises/photos/incline-barbell-bench-press-0.jpg', '/exercises/photos/incline-barbell-bench-press-1.jpg', ARRAY['Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on you upper chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], FALSE),
  ('incline-dumbbell-press', 'Incline Dumbbell Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/incline-dumbbell-press.gif', '/exercises/photos/incline-dumbbell-press-0.jpg', '/exercises/photos/incline-dumbbell-press-1.jpg', ARRAY['Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.', 'Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.', 'Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.']::text[], FALSE),
  ('dumbbell-bench-press', 'Dumbbell Bench Press', 'chest'::public.muscle_group, ARRAY['shoulders', 'triceps']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-bench-press.gif', '/exercises/photos/dumbbell-bench-press-0.jpg', '/exercises/photos/dumbbell-bench-press-1.jpg', ARRAY['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.', 'Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], FALSE),
  ('cable-chest-fly', 'Cable Chest Fly', 'chest'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-chest-fly.gif', '/exercises/photos/cable-chest-fly-0.jpg', '/exercises/photos/cable-chest-fly-1.jpg', ARRAY['Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.', 'Lay flat on the bench and keep your feet on the ground.', 'Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.', 'Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.', 'Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.']::text[], FALSE),
  ('pec-deck-fly', 'Pec Deck Fly', 'chest'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/pec-deck-fly.gif', '/exercises/photos/pec-deck-fly-0.jpg', '/exercises/photos/pec-deck-fly-1.jpg', ARRAY['Sit on the machine with your back flat on the pad.', 'Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.', 'Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.', 'Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('chest-dip', 'Chest Dip', 'chest'::public.muscle_group, ARRAY['triceps', 'shoulders']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'weighted_bodyweight'::public.tracking_type, '/exercises/gifs/chest-dip.gif', '/exercises/photos/chest-dip-0.jpg', '/exercises/photos/chest-dip-1.jpg', ARRAY['For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.', 'While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.', 'Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], FALSE),
  ('push-up', 'Push-Up', 'chest'::public.muscle_group, ARRAY['triceps', 'shoulders', 'core']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/push-up.gif', '/exercises/photos/push-up-0.jpg', '/exercises/photos/push-up-1.jpg', ARRAY['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.', 'Next, lower yourself downward until your chest almost touches the floor as you inhale.', 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.', 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[], FALSE),
  ('pull-up', 'Pull-Up', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'weighted_bodyweight'::public.tracking_type, '/exercises/gifs/pull-up.gif', '/exercises/photos/pull-up-0.jpg', '/exercises/photos/pull-up-1.jpg', ARRAY['Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], FALSE),
  ('lat-pulldown', 'Lat Pulldown', 'back'::public.muscle_group, ARRAY['biceps']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/lat-pulldown.gif', '/exercises/photos/lat-pulldown-0.jpg', '/exercises/photos/lat-pulldown-1.jpg', ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.', 'After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.']::text[], FALSE),
  ('barbell-bent-over-row', 'Barbell Bent-Over Row', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-bent-over-row.gif', '/exercises/photos/barbell-bent-over-row-0.jpg', '/exercises/photos/barbell-bent-over-row-1.jpg', ARRAY['Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.', 'Then inhale and slowly lower the barbell back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('seated-cable-row', 'Seated Cable Row', 'back'::public.muscle_group, ARRAY['biceps']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/seated-cable-row.gif', '/exercises/photos/seated-cable-row-0.jpg', '/exercises/photos/seated-cable-row-1.jpg', ARRAY['For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the V-bar handles.', 'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('single-arm-dumbbell-row', 'Single-Arm Dumbbell Row', 'back'::public.muscle_group, ARRAY['biceps', 'forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/single-arm-dumbbell-row.gif', '/exercises/photos/single-arm-dumbbell-row-0.jpg', '/exercises/photos/single-arm-dumbbell-row-1.jpg', ARRAY['Choose a flat bench and place a dumbbell on each side of it.', 'Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.', 'Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.', 'Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.', 'Lower the resistance straight down to the starting position. Breathe in as you perform this step.']::text[], FALSE),
  ('chest-supported-row', 'Chest-Supported Dumbbell Row', 'back'::public.muscle_group, ARRAY['biceps', 'shoulders']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/chest-supported-row.gif', '/exercises/photos/chest-supported-row-0.jpg', '/exercises/photos/chest-supported-row-1.jpg', ARRAY['Using a neutral grip, lean into an incline bench.', 'Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.', 'Retract the shoulder blades and flex the elbows to row the dumbbells to your side.', 'Pause at the top of the motion, and then return to the starting position.']::text[], FALSE),
  ('conventional-deadlift', 'Conventional Deadlift', 'back'::public.muscle_group, ARRAY['hamstrings', 'glutes', 'forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/conventional-deadlift.gif', '/exercises/photos/conventional-deadlift-0.jpg', '/exercises/photos/conventional-deadlift-1.jpg', ARRAY['Stand in front of a loaded barbell.', 'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.', 'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.', 'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.', 'Perform the amount of repetitions prescribed in the program.']::text[], FALSE),
  ('face-pull', 'Cable Face Pull', 'back'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/face-pull.gif', '/exercises/photos/face-pull-0.jpg', '/exercises/photos/face-pull-1.jpg', ARRAY['Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.']::text[], FALSE),
  ('barbell-overhead-press', 'Barbell Overhead Press', 'shoulders'::public.muscle_group, ARRAY['triceps', 'core']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-overhead-press.gif', '/exercises/photos/barbell-overhead-press-0.jpg', '/exercises/photos/barbell-overhead-press-1.jpg', ARRAY['Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.', 'Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.', 'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the collarbone slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.']::text[], FALSE),
  ('seated-dumbbell-shoulder-press', 'Seated Dumbbell Shoulder Press', 'shoulders'::public.muscle_group, ARRAY['triceps']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/seated-dumbbell-shoulder-press.gif', '/exercises/photos/seated-dumbbell-shoulder-press-0.jpg', '/exercises/photos/seated-dumbbell-shoulder-press-1.jpg', ARRAY['While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.', 'Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.', 'Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.', 'Now, exhale and push the dumbbells upward until they touch at the top.', 'Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.']::text[], FALSE),
  ('dumbbell-lateral-raise', 'Dumbbell Lateral Raise', 'shoulders'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-lateral-raise.gif', '/exercises/photos/dumbbell-lateral-raise-0.jpg', '/exercises/photos/dumbbell-lateral-raise-1.jpg', ARRAY['Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.', 'While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbells back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-lateral-raise', 'Cable Lateral Raise', 'shoulders'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-lateral-raise.gif', '/exercises/photos/cable-lateral-raise-0.jpg', '/exercises/photos/cable-lateral-raise-1.jpg', ARRAY['Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.', 'Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.', 'Bend forward while keeping your back flat and rest your torso on the thighs.', 'Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.', 'While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.']::text[], FALSE),
  ('reverse-pec-deck-fly', 'Reverse Pec Deck Fly', 'shoulders'::public.muscle_group, ARRAY['back']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/reverse-pec-deck-fly.gif', '/exercises/photos/reverse-pec-deck-fly-0.jpg', '/exercises/photos/reverse-pec-deck-fly-1.jpg', ARRAY['To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).', 'Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.', 'Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.', 'The arms should be elevated until they are parallel to the floor.', 'Feel the contraction and slowly lower the weights back down to the starting position while inhaling.']::text[], FALSE),
  ('dumbbell-front-raise', 'Dumbbell Front Raise', 'shoulders'::public.muscle_group, ARRAY['chest']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-front-raise.gif', '/exercises/photos/dumbbell-front-raise-0.jpg', '/exercises/photos/dumbbell-front-raise-1.jpg', ARRAY['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.', 'Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.', 'Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.']::text[], FALSE),
  ('barbell-curl', 'Barbell Bicep Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-curl.gif', '/exercises/photos/barbell-curl-0.jpg', '/exercises/photos/barbell-curl-1.jpg', ARRAY['Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-bicep-curl', 'Dumbbell Bicep Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-bicep-curl.gif', '/exercises/photos/dumbbell-bicep-curl-0.jpg', '/exercises/photos/dumbbell-bicep-curl-1.jpg', ARRAY['Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.', 'Then, inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('hammer-curl', 'Dumbbell Hammer Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/hammer-curl.gif', '/exercises/photos/hammer-curl-0.jpg', '/exercises/photos/hammer-curl-1.jpg', ARRAY['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.', 'After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('incline-dumbbell-curl', 'Incline Dumbbell Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/incline-dumbbell-curl.gif', '/exercises/photos/incline-dumbbell-curl-0.jpg', '/exercises/photos/incline-dumbbell-curl-1.jpg', ARRAY['Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-bicep-curl', 'Cable Bicep Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-bicep-curl.gif', '/exercises/photos/cable-bicep-curl-0.jpg', '/exercises/photos/cable-bicep-curl-1.jpg', ARRAY['Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the curl bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('preacher-curl', 'Preacher Curl', 'biceps'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/preacher-curl.gif', '/exercises/photos/preacher-curl-0.jpg', '/exercises/photos/preacher-curl-1.jpg', ARRAY['To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.', 'With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-triceps-pushdown', 'Cable Rope Triceps Pushdown', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-triceps-pushdown.gif', '/exercises/photos/cable-triceps-pushdown-0.jpg', '/exercises/photos/cable-triceps-pushdown-1.jpg', ARRAY['Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.', 'Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('overhead-cable-triceps-extension', 'Overhead Cable Triceps Extension', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/overhead-cable-triceps-extension.gif', '/exercises/photos/overhead-cable-triceps-extension-0.jpg', '/exercises/photos/overhead-cable-triceps-extension-1.jpg', ARRAY['Attach a rope to the bottom pulley of the pulley machine.', 'Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.', 'Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.', 'Return to the starting position by flexing your triceps as you breathe out.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('barbell-skullcrusher', 'Skullcrusher (Lying Triceps Extension)', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-skullcrusher.gif', '/exercises/photos/barbell-skullcrusher-0.jpg', '/exercises/photos/barbell-skullcrusher-1.jpg', ARRAY['Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.', 'Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.', 'Lift the bar back to the starting position by extending the elbow and exhaling.', 'Repeat.']::text[], FALSE),
  ('dumbbell-overhead-triceps-extension', 'Dumbbell Overhead Triceps Extension', 'triceps'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-overhead-triceps-extension.gif', '/exercises/photos/dumbbell-overhead-triceps-extension-0.jpg', '/exercises/photos/dumbbell-overhead-triceps-extension-1.jpg', ARRAY['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.', 'Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.', 'Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.', 'Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.', 'Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.']::text[], FALSE),
  ('close-grip-bench-press', 'Close-Grip Bench Press', 'triceps'::public.muscle_group, ARRAY['chest', 'shoulders']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/close-grip-bench-press.gif', '/exercises/photos/close-grip-bench-press-0.jpg', '/exercises/photos/close-grip-bench-press-1.jpg', ARRAY['Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], FALSE),
  ('barbell-back-squat', 'Barbell Back Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings', 'core']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-back-squat.gif', '/exercises/photos/barbell-back-squat-0.jpg', '/exercises/photos/barbell-back-squat-1.jpg', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.', 'Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.', 'Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.']::text[], FALSE),
  ('front-squat', 'Barbell Front Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'core']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/front-squat.gif', '/exercises/photos/front-squat-0.jpg', '/exercises/photos/front-squat-1.jpg', ARRAY['To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.', 'Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves. Keep your knees aligned with your feet by consciously using your abductors to push your knees out as you squat.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position.']::text[], FALSE),
  ('leg-press', 'Leg Press', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/leg-press.gif', '/exercises/photos/leg-press-0.jpg', '/exercises/photos/leg-press-1.jpg', ARRAY['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.', 'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.', 'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.']::text[], FALSE),
  ('bulgarian-split-squat', 'Dumbbell Bulgarian Split Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/bulgarian-split-squat.gif', '/exercises/photos/bulgarian-split-squat-0.jpg', '/exercises/photos/bulgarian-split-squat-1.jpg', ARRAY['Position yourself into a staggered stance with the rear foot elevated and front foot forward.', 'Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.', 'Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.', 'At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.']::text[], FALSE),
  ('dumbbell-lunge', 'Dumbbell Lunge', 'quads'::public.muscle_group, ARRAY['glutes', 'hamstrings']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-lunge.gif', '/exercises/photos/dumbbell-lunge-0.jpg', '/exercises/photos/dumbbell-lunge-1.jpg', ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[], FALSE),
  ('leg-extension', 'Leg Extension', 'quads'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/leg-extension.gif', '/exercises/photos/leg-extension-0.jpg', '/exercises/photos/leg-extension-1.jpg', ARRAY['For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.', 'Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.', 'Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.', 'Repeat for the recommended amount of times.']::text[], FALSE),
  ('goblet-squat', 'Dumbbell Goblet Squat', 'quads'::public.muscle_group, ARRAY['glutes', 'core']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/goblet-squat.gif', '/exercises/photos/goblet-squat-0.jpg', '/exercises/photos/goblet-squat-1.jpg', ARRAY['Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.', 'Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.', 'At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.']::text[], FALSE),
  ('romanian-deadlift', 'Barbell Romanian Deadlift', 'hamstrings'::public.muscle_group, ARRAY['glutes', 'back']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/romanian-deadlift.gif', '/exercises/photos/romanian-deadlift-0.jpg', '/exercises/photos/romanian-deadlift-1.jpg', ARRAY['Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.', 'Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.', 'Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.', 'Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-romanian-deadlift', 'Dumbbell Romanian Deadlift', 'hamstrings'::public.muscle_group, ARRAY['glutes', 'back']::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-romanian-deadlift.gif', '/exercises/photos/dumbbell-romanian-deadlift-0.jpg', '/exercises/photos/dumbbell-romanian-deadlift-1.jpg', ARRAY['Grasp a couple of dumbbells holding them by your side at arm''s length.', 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement', 'Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('lying-leg-curl', 'Lying Leg Curl', 'hamstrings'::public.muscle_group, ARRAY['calves']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/lying-leg-curl.gif', '/exercises/photos/lying-leg-curl-0.jpg', '/exercises/photos/lying-leg-curl-1.jpg', ARRAY['Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.', 'Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.', 'As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('seated-leg-curl', 'Seated Leg Curl', 'hamstrings'::public.muscle_group, ARRAY['calves']::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/seated-leg-curl.gif', '/exercises/photos/seated-leg-curl-0.jpg', '/exercises/photos/seated-leg-curl-1.jpg', ARRAY['Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.', 'Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.', 'As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('barbell-hip-thrust', 'Barbell Hip Thrust', 'glutes'::public.muscle_group, ARRAY['hamstrings', 'quads']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/barbell-hip-thrust.gif', '/exercises/photos/barbell-hip-thrust-0.jpg', '/exercises/photos/barbell-hip-thrust-1.jpg', ARRAY['Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.', 'Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.', 'Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.']::text[], FALSE),
  ('cable-pull-through', 'Cable Pull-Through', 'glutes'::public.muscle_group, ARRAY['hamstrings']::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-pull-through.gif', '/exercises/photos/cable-pull-through-0.jpg', '/exercises/photos/cable-pull-through-1.jpg', ARRAY['Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.', 'Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips.']::text[], FALSE),
  ('glute-bridge', 'Barbell Glute Bridge', 'glutes'::public.muscle_group, ARRAY['hamstrings']::public.muscle_group[], 'barbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/glute-bridge.gif', '/exercises/photos/glute-bridge-0.jpg', '/exercises/photos/glute-bridge-1.jpg', ARRAY['Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.', 'Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.', 'Extend as far as possible, then reverse the motion to return to the starting position.']::text[], FALSE),
  ('hip-abduction-machine', 'Seated Hip Abduction Machine', 'glutes'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/hip-abduction-machine.gif', '/exercises/photos/hip-abduction-machine-0.jpg', '/exercises/photos/hip-abduction-machine-1.jpg', ARRAY['To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them away from each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('standing-calf-raise', 'Standing Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/standing-calf-raise.gif', '/exercises/photos/standing-calf-raise-0.jpg', '/exercises/photos/standing-calf-raise-1.jpg', ARRAY['Adjust the padded lever of the calf raise machine to fit your height.', 'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('seated-calf-raise', 'Seated Calf Raise', 'calves'::public.muscle_group, '{}'::public.muscle_group[], 'machine'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/seated-calf-raise.gif', '/exercises/photos/seated-calf-raise-0.jpg', '/exercises/photos/seated-calf-raise-1.jpg', ARRAY['Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.', 'Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.', 'Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.', 'Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.', 'Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.']::text[], FALSE),
  ('plank', 'Plank', 'core'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'duration'::public.tracking_type, '/exercises/gifs/plank.gif', '/exercises/photos/plank-0.jpg', '/exercises/photos/plank-1.jpg', ARRAY['Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.', 'Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.']::text[], FALSE),
  ('hanging-leg-raise', 'Hanging Leg Raise', 'core'::public.muscle_group, ARRAY['forearms']::public.muscle_group[], 'bodyweight'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/hanging-leg-raise.gif', '/exercises/photos/hanging-leg-raise-0.jpg', '/exercises/photos/hanging-leg-raise-1.jpg', ARRAY['Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.', 'Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.', 'Go back slowly to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('cable-crunch', 'Kneeling Cable Crunch', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'cable'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/cable-crunch.gif', '/exercises/photos/cable-crunch-0.jpg', '/exercises/photos/cable-crunch-1.jpg', ARRAY['Kneel below a high pulley that contains a rope attachment.', 'Grasp cable rope attachment and lower the rope until your hands are placed next to your face.', 'Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.', 'With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.', 'Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.']::text[], FALSE),
  ('ab-wheel-rollout', 'Ab Wheel Rollout', 'core'::public.muscle_group, ARRAY['shoulders']::public.muscle_group[], 'other'::public.equipment_type, 'bodyweight_reps'::public.tracking_type, '/exercises/gifs/ab-wheel-rollout.gif', '/exercises/photos/ab-wheel-rollout-0.jpg', '/exercises/photos/ab-wheel-rollout-1.jpg', ARRAY['Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.', 'Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.', 'Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.', 'After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[], FALSE),
  ('russian-twist', 'Russian Twist', 'core'::public.muscle_group, '{}'::public.muscle_group[], 'bodyweight'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/russian-twist.gif', '/exercises/photos/russian-twist-0.jpg', '/exercises/photos/russian-twist-1.jpg', ARRAY['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.', 'Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.', 'Twist your torso to the right side until your arms are parallel with the floor while breathing out.', 'Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.', 'Repeat for the recommended amount of repetitions.']::text[], FALSE),
  ('dumbbell-wrist-curl', 'Dumbbell Wrist Curl', 'forearms'::public.muscle_group, '{}'::public.muscle_group[], 'dumbbell'::public.equipment_type, 'weight_reps'::public.tracking_type, '/exercises/gifs/dumbbell-wrist-curl.gif', '/exercises/photos/dumbbell-wrist-curl-0.jpg', '/exercises/photos/dumbbell-wrist-curl-1.jpg', ARRAY['Start out by placing two dumbbells on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise.']::text[], FALSE)
ON CONFLICT (slug) DO UPDATE SET
